#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    string S;
    S.reserve(N);
    for (int i = 0; i < N; ++i) {
        int d;
        cin >> d;
        S.push_back('0' + d);
    }

    if (S[0] == '0') {
        return 0;
    }

    for (int L = 1; L <= N; ++L) {
        string A = S.substr(0, L);
        string cur = A;
        int pos = 0;
        bool ok = true;

        while (pos < N) {
            if (pos + (int)cur.size() > N) {
                ok = false;
                break;
            }
            if (S.compare(pos, cur.size(), cur) != 0) {
                ok = false;
                break;
            }
            pos += cur.size();

            int i = (int)cur.size() - 1;
            while (i >= 0 && cur[i] == '9') {
                cur[i] = '0';
                --i;
            }
            if (i < 0) {
                cur = "1" + cur;
            } else {
                ++cur[i];
            }
        }

        if (ok && pos == N) {
            cout << A << '\n';
            return 0;
        }
    }

    return 0;
}
